<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller;use App\Http\Requests\Api\DeviceRequest;use App\Http\Resources\DeviceResource;use App\Models\ControllerDevice;use App\Repositories\DeviceRepository;use App\Services\CrudService;
class DeviceController extends Controller {private CrudService $service;public function __construct(DeviceRepository $r){$this->service=new CrudService($r);}public function index(){return DeviceResource::collection($this->service->all(['controller.machine']));}public function store(DeviceRequest $r){return (new DeviceResource($this->service->create($r->validated())))->response()->setStatusCode(201);}public function show(ControllerDevice $device){return new DeviceResource($device->load('controller.machine'));}public function update(DeviceRequest $r,ControllerDevice $device){return new DeviceResource($this->service->update($device,$r->validated()));}public function destroy(ControllerDevice $device){$this->service->delete($device);return response()->noContent();}}
